export const locales = ["en", "fr"] as const;
export type Locale = (typeof locales)[number];

export const defaultLocale: Locale = "en";
export const LOCALE_COOKIE = "NEXT_LOCALE";

// generated by yarn cv:export; a language without its own CV falls back to English
const cvFiles = {
  en: "/Abdulhamid-Afolabi-CV.pdf",
  fr: "/Abdulhamid-Afolabi-CV-FR.pdf"
} satisfies Record<Locale, string | null>;

export const cvFor = (locale: Locale): string => cvFiles[locale] ?? cvFiles.en;

export const isLocale = (value?: string): value is Locale =>
  locales.includes(value as Locale);
